/**
 * Startup migration: raise lock_wait in existing backup jobs.
 *
 * lock_wait is frozen into each job's YAML at save time. Jobs used to get 60s
 * (or nothing, i.e. borg's 1s default), so two jobs sharing a repository failed
 * whenever the first one held the lock for longer than that. Only configs
 * generated by Borgmatic-UI are touched, and only when they still carry the
 * legacy value or none at all — a deliberately customised value is kept.
 *
 * The file is edited as text (one line replaced or appended) rather than
 * re-serialized, so hook scripts and comments stay byte-identical.
 */

const fs = require('fs-extra');
const path = require('path');
const yaml = require('js-yaml');
const { isDeepStrictEqual } = require('util');

const appConfig = require('../../config');
const { DEFAULT_LOCK_WAIT_SECONDS, LEGACY_LOCK_WAIT_SECONDS } = require('../../utils/borg-defaults');

const GENERATED_HEADER = '# Generated by Borgmatic-UI';
const LEGACY_LINE = new RegExp(`^lock_wait:[ \\t]*${LEGACY_LOCK_WAIT_SECONDS}[ \\t]*$`, 'm');

/**
 * Compute the migrated text for one config, or null when nothing should change.
 *
 * @param {string} text
 * @returns {string|null}
 */
function migrateLockWaitText(text) {
    if (!text.startsWith(GENERATED_HEADER)) return null;

    const config = yaml.load(text);
    if (!config || typeof config !== 'object' || Array.isArray(config)) return null;

    let newText;
    if (config.lock_wait === undefined) {
        newText = `${text.replace(/\s*$/, '')}\nlock_wait: ${DEFAULT_LOCK_WAIT_SECONDS}\n`;
    } else if (config.lock_wait === LEGACY_LOCK_WAIT_SECONDS && LEGACY_LINE.test(text)) {
        newText = text.replace(LEGACY_LINE, `lock_wait: ${DEFAULT_LOCK_WAIT_SECONDS}`);
    } else {
        return null;
    }

    const expected = { ...config, lock_wait: DEFAULT_LOCK_WAIT_SECONDS };
    if (!isDeepStrictEqual(yaml.load(newText), expected)) {
        throw new Error('edited config did not parse back as expected; left unchanged');
    }
    return newText;
}

/**
 * @param {object} [options]
 * @param {string} [options.backupsDir] — override for tests
 * @returns {Promise<{filesChanged: number, errors: string[]}>}
 */
async function migrateLockWait(options = {}) {
    const backupsDir = options.backupsDir || path.join(appConfig.configDir, 'borgmatic.d');
    const result = { filesChanged: 0, errors: [] };

    if (!(await fs.pathExists(backupsDir))) return result;

    const files = (await fs.readdir(backupsDir))
        .filter((f) => f.endsWith('.yaml') || f.endsWith('.yml'));

    for (const filename of files) {
        const filePath = path.join(backupsDir, filename);
        try {
            const text = await fs.readFile(filePath, 'utf8');
            const newText = migrateLockWaitText(text);
            if (newText === null) continue;

            await fs.writeFile(filePath, newText);
            result.filesChanged++;
        } catch (error) {
            result.errors.push(`${filename}: ${error.message}`);
        }
    }

    if (result.filesChanged > 0) {
        console.log(`🔧 lock_wait migration: set lock_wait to ${DEFAULT_LOCK_WAIT_SECONDS}s in ${result.filesChanged} job(s)`);
    }
    for (const err of result.errors) {
        console.warn(`⚠️  lock_wait migration error: ${err}`);
    }

    return result;
}

module.exports = {
    migrateLockWait,
    // exported for tests
    migrateLockWaitText,
};
